      createArtifact(payload?: BackupRestoreArtifactCreateRequest): Promise<BackupRestoreArtifactReceipt>;
      restoreArtifact(payload: BackupRestoreArtifactRestoreRequest): Promise<BackupRestoreArtifactRestoreReport>;
      executeArtifactRestore(payload: BackupRestoreArtifactRestoreRequest): Promise<BackupRestoreArtifactRestoreReport>;
      startRestoreMode(payload?: BackupRestoreModeStartRequest): Promise<BackupRestoreModeReport>;
      restoreModeStatus(restoreId: string): Promise<BackupRestoreModeReport>;
      postRestoreValidation(restoreId: string, payload?: BackupRestorePostRestoreValidationRequest): Promise<BackupRestorePostRestoreValidationReport>;
      approveResume(restoreId: string, payload?: BackupRestoreResumeApprovalRequest): Promise<BackupRestoreModeReport>;
